import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void adicionaAlemDaCapacidadeInicial() {
        var l = new Solution.IntList();
        for (int i = 0; i < 10; i++) l.add(i);
        assertEquals(10, l.size());
        assertEquals(9, l.get(9));
    }

    @Test void removeDeslocaElementos() {
        var l = new Solution.IntList();
        l.add(1); l.add(2); l.add(3);
        assertEquals(2, l.removeAt(1));
        assertEquals(3, l.get(1));
        assertEquals(2, l.size());
    }

    @Test void indiceInvalidoFalha() {
        var l = new Solution.IntList();
        assertThrows(IndexOutOfBoundsException.class, () -> l.get(0));
        assertThrows(IndexOutOfBoundsException.class, () -> l.set(-1, 5));
    }
}
